# ── local helpers ───────────────────────────────────────────────────────────

def _run(cmd, timeout=90, secret=None, cap=4000, stdin=None):
    """Run a local command; optionally feed ONE secret via SSH_ASKPASS, and
    text on its standard input (never on a command line, which any user of
    the host can read)."""
    env = dict(os.environ)
    helper = None
    if secret is not None:
        helper = tempfile.NamedTemporaryFile("w", suffix="_askpass.sh",
                                             delete=False, dir=os.path.expanduser("~"))
        helper.write('#!/bin/sh\nprintf "%s\\n" "$FEMTO_SECRET"\n')
        helper.close()
        os.chmod(helper.name, stat.S_IRWXU)
        env.update(FEMTO_SECRET=secret, SSH_ASKPASS=helper.name,
                   SSH_ASKPASS_REQUIRE="force", DISPLAY=":0")
    try:
        p = subprocess.run(cmd, capture_output=True, text=True,
                           timeout=timeout, env=env, input=stdin)
    finally:
        if helper:
            try:
                os.unlink(helper.name)
            except OSError:
                pass
    return {"rc": p.returncode, "out": (p.stdout or "")[-cap:],
            "err": (p.stderr or "")[-800:]}


def _master_alive(sock, dest, opts=None):
    if not os.path.exists(sock):
        return False
    return _run(["ssh", "-S", sock, "-O", "check"] + (opts or []) + [dest],
                timeout=15)["rc"] == 0


def _shq(s):
    """Single-quote a string for safe interpolation into a remote shell."""
    return "'" + s.replace("'", "'\\''") + "'"


# ── per-user remote helpers ─────────────────────────────────────────────────

def _fwd_port(user):
    return FA_FWD_PORT_BASE + (zlib.crc32(user.encode()) % 400)


def _socks(user):
    return f"{CM_DIR}/gateway-{user}", f"{CM_DIR}/ifarm-{user}"


_WS_CACHE = {}


def _workspace(user):
    """The user's workspace = the folder they git-cloned (one folder = everything).
    Recorded in <area>/.jam_workspace at setup time; the default is the
    conventional clone target."""
    if user not in _WS_CACHE:
        area = _area(user)
        r = _remote(user, f"cat {area}/.jam_workspace 2>/dev/null", timeout=30)
        ws = (r.get("out") or "").strip() or f"{area}/fitpack_legacy"
        # rc 1 is a missing marker (the default applies); an SSH failure (255) is
        # not remembered, or the default would stand for the rest of the process.
        if r.get("rc", 0) in (0, 1):
            _WS_CACHE[user] = ws
        return ws
    return _WS_CACHE[user]


def _container_exec(fp, extra_path="", env=None):
    """apptainer exec prefix that runs python3 inside the site's image with the
    workspace (and extra_path, if any) on the path."""
    c = SITE["container"]
    binds = " ".join(f"--bind {b}" for b in c.get("binds", []))
    pypath = fp + (f":{extra_path}" if extra_path else "")
    envs = "".join(f" --env {k}={_shq(str(v))}" for k, v in (env or {}).items())
    return (f"apptainer exec {binds} --env PYTHONPATH={_shq(pypath)} --env FITPACK={_shq(fp)}{envs} "
            f"{c['image']} python3")


def _remote(user, cmd, timeout=120, cap=4000, stdin=None):
    """Run a shell command on the compute host through the user's chain;
    stdin, if given, is what the command reads on its standard input."""
    _, fa = _socks(user)
    return _run(["ssh", "-S", fa, "-p", str(_fwd_port(user)), f"{user}@localhost",
                 "bash -lc " + _shq(cmd)], timeout=timeout, cap=cap, stdin=stdin)


def _run_ifarm_py(user, code, apptainer=False, timeout=300, cap=4000, extra_path="", env=None):
    """Ship a python snippet to the compute host as base64 and run it (avoids
    all shell-quoting issues). apptainer=True runs inside the site's image
    (needed for fitpack/numpy imports)."""
    b64 = base64.b64encode(code.encode()).decode()
    unpack = "base64 -d"
    if len(b64) > 60000:
        # The command line is one SSH argument (at most 128 KiB): a long
        # script travels compressed and the host's python3 unpacks it.
        b64 = base64.b64encode(zlib.compress(code.encode(), 9)).decode()
        if len(b64) > 60000:
            # Large pinned ensembles/registry records must not become SSH argv.
            runner = _container_exec(_workspace(user), extra_path, env) if apptainer else 'python3'
            return _remote(user, runner + ' -', timeout=timeout, cap=cap, stdin=code)
        unpack = ("base64 -d | python3 -c " +
                  _shq("import sys, zlib; sys.stdout.buffer.write(zlib.decompress(sys.stdin.buffer.read()))"))
    if apptainer:
        run = f"echo {b64} | {unpack} | {_container_exec(_workspace(user), extra_path, env)} -"
    else:
        run = f"echo {b64} | {unpack} | python3"
    return _remote(user, run, timeout=timeout, cap=cap)


def _fill(template, **values):
    """A python snippet: template with each __NAME__ replaced by repr(value),
    in one pass, so a value that contains another placeholder (a campaign or
    folder name, say) stays as it is."""
    subs = {f"__{k}__": repr(v) for k, v in values.items()}
    return re.sub("|".join(map(re.escape, subs)), lambda m: subs[m.group(0)], template)


# ── access ──────────────────────────────────────────────────────────────────
#
# A request carries "Authorization: Bearer <dashboard token>". A token of the
# owner resolves to the owner, and every tool acts as the owner and nobody
# else. Tools take no username argument; the functions' username parameter
# serves calls between them, and _resolve_user refuses any other name.

_tls = threading.local()
AUTH_HELP = (("This gateway takes its own token, not the dashboard token: the owner gets it with "
              "`python3 redeploy_jam.py token` and exports it as JAM_GW_TOKEN. Configure the MCP client to "
              "send the header 'Authorization: Bearer <that token>', or paste it into the panel page when it "
              "asks for one. On a shared gateway, use the token its owner gave you.")
             if AUTH_MODE == "token" else
             ("This gateway needs your LQCDMCP dashboard token (the one from the dashboard "
              "login you launched the gateway with). Configure the MCP client to send the header "
              "'Authorization: Bearer <token>', or paste it into the panel page when it asks for "
              "one. When the dashboard login expires, log in again and update the token."))

# ── refusal codes ───────────────────────────────────────────────────────────
#
# Every refusal a tool returns carries a stable "code" beside its message, and
# the audit log records the same code, so refusals can be counted by kind
# (the failure table of the paper) without parsing message text. The message
# stays the human explanation and may change; the code does not.
REFUSAL_CODES = (
    # transport and identity
    "AUTH_REQUIRED", "IDENTITY_MISMATCH", "NOT_SHARED", "BAD_USERNAME", "UNKNOWN_TOOL", "TOOL_DENIED",
    "HIDDEN_TOOL", "ADMIN_REQUIRED", "ADMIN_DISABLED", "CHAIN_DOWN",
    # the campaign card and the workspace
    "CARD_INVALID", "CATALOG_REQUIRED", "CATALOG_MISMATCH", "CONFIRM_TOO_SOON", "CONFIRM_NOT_SHOWN", "LIBRARY_UNREADABLE", "WORKSPACE_NOT_READY", "WORKSPACE_MISSING", "DATA_FILE_MISSING",
    "PRIOR_SOURCE_INVALID", "PRIOR_ARCHIVE_DENIED", "NO_DATA", "CONFIG_ONLY_UNSUPPORTED", "DIRTY_CHECKOUT",
    "OUTSIDE_AREA", "OUTSIDE_READ_ROOTS", "BAD_ARGUMENT",
    # submission and the queue
    "MATERIALIZE_FAILED", "SBATCH_REFUSED", "SCANCEL_FAILED", "CONFIRM_REQUIRED", "IDEMPOTENT_REPLAY",
    "NOT_FOUND", "QUEUE_UNKNOWN", "STILL_QUEUED",
    # reproduction records
    "RECORD_MISSING", "RECORD_UNREADABLE", "RECORD_INCOMPLETE", "WORKSPACE_DRIFT", "REBUILD_FAILED",
    "CHECKPOINT_INVALID",
    # campaign and data files on the cluster that could not be read or written
    "READ_FAILED", "WRITE_FAILED",
    # the gateway's own code path
    "NOT_A_JOB", "BAD_STAGE", "BAD_PATH", "HASH_MISMATCH", "VERIFY_FAILED", "INSTALL_FAILED",
    "PANEL_ONLY", "INTERNAL_ERROR", "ERROR_UNCODED",
)


def _refuse(code, message, status="error", **extra):
    """A refusal: status, code and message, plus whatever else the caller adds."""
    assert code in REFUSAL_CODES, code
    return {"status": status, "code": code, "message": message, **extra}


def _outcome(result):
    """(status, code, is_error) of a tool's reply, for the audit log. A dict
    reply is read by its status and code; a refusal that predates the codes
    is ERROR_UNCODED, so it can be found and given one."""
    if isinstance(result, dict) and "content" in result and "isError" in result:
        body = result.get("structuredContent")
        if body is None:
            # A bare string reply ("unknown tool", "error: ...").
            text = (result.get("content") or [{}])[0].get("text", "") if result.get("content") else ""
            if text == "unknown tool":
                return "error", "UNKNOWN_TOOL", True
            return ("error", "INTERNAL_ERROR", True) if result.get("isError") else ("ok", None, False)
        is_error = bool(result.get("isError"))
    else:
        body, is_error = result, False
    if not isinstance(body, dict):
        return "ok", None, is_error
    status = str(body.get("status") or "ok")
    code = body.get("code")
    if code is None:
        code = {"unauthorized": "AUTH_REQUIRED", "disconnected": "CHAIN_DOWN", "needs_confirmation": "CONFIRM_REQUIRED",
                "invalid": "CARD_INVALID", "error": "ERROR_UNCODED"}.get(status)
    return status, code, is_error or status in ("error", "unauthorized", "disconnected", "invalid")


def _req_sid(hdrs):
    sid = (hdrs.get("Mcp-Session-Id") or hdrs.get("mcp-session-id") or "").strip()
    return sid or ("jam-" + secrets.token_hex(8))


def _sha(token):
    return hashlib.sha256(token.encode()).hexdigest()


def _ensure_access_dir():
    os.makedirs(ACCESS_DIR, mode=0o700, exist_ok=True)
    os.chmod(ACCESS_DIR, 0o700)


def _identify(auth_header):
    """Resolve a bearer token to the username it acts as, or '' if unusable."""
    if not auth_header or auth_header[:7].lower() != "bearer ":
        return ""
    token = auth_header[7:].strip()
    if token[:7].lower() == "bearer ":
        # A client that was given "Bearer <token>" as the token sends it twice.
        token = token[7:].strip()
    if not token or len(token) > 1024:
        return ""
    if AUTH_MODE == "token":
        h = _sha(token)
        if TOKEN_SHA256 and hmac.compare_digest(h, TOKEN_SHA256):
            _tls.auth = "token"
            return GATEWAY_OWNER
        # Every entry is compared (no early exit) and exactly one must match.
        hits = [name for name, hh in USERS_SHA256.items() if hmac.compare_digest(h, hh)]
        if len(hits) == 1:
            _tls.auth = "user"
            return hits[0]
        return ""
    if TEST_TOKEN and hmac.compare_digest(token, TEST_TOKEN):
        _tls.auth = "test"
        return GATEWAY_OWNER
    user = _dashboard_identify(token, _sha(token))
    _tls.auth = "dashboard" if user else "none"      # which check accepted the token, for the audit log
    return user


# ── dashboard tokens ─────────────────────────────────────────────────────────
#
# The LQCDMCP dashboard token (Globus login) opens this gateway: the
# dashboard is asked who the token's user is and which MCP servers they
# launched, and the token is the owner's when that user is this gateway's
# owner and the list holds this gateway (its name, owner and Slurm job). A
# listing the gateway cannot read is a refusal. The proxy itself forwards
# /cloud/<name>/mcp without checking anyone. As of October 2026 the dashboard
# does not verify the token either (validate_user answers for whatever
# username it is given), so this check only keeps out callers who name the
# wrong gateway; it is not what keeps a gateway with an open cluster chain
# private. Until the dashboard checks tokens, stopping the gateway is.

DASHBOARD_URL = os.environ.get("JAM_GW_DASHBOARD_URL", f"{PROXY}/jlab/")
DASHBOARD_AUTH = os.environ.get("JAM_GW_DASHBOARD_AUTH", "1") != "0"
_DASH_CACHE = {}                    # token hash -> (username or '', expires at)
_DASH_LOCK = threading.Lock()


def _dashboard_call(token, method, params, sid=None, timeout=20):
    body = json.dumps({"jsonrpc": "2.0", "id": 1, "method": method, "params": params}).encode()
    hdrs = {"Authorization": "Bearer " + token, "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream"}
    if sid:
        hdrs["Mcp-Session-Id"] = sid
    with urllib.request.urlopen(urllib.request.Request(DASHBOARD_URL, data=body, headers=hdrs),
                                timeout=timeout) as r:
        sid = r.headers.get("Mcp-Session-Id") or sid
        raw = r.read().decode(errors="replace")
    events = re.findall(r"^data: (.*)$", raw, re.M) or [raw]
    for ev in reversed(events):
        try:
            return json.loads(ev), sid
        except ValueError:
            continue
    return {}, sid


def _dashboard_json(resp):
    """The JSON a dashboard tool result carries: each content text that parses
    as JSON, and the structuredContent."""
    res = (resp or {}).get("result") or {}
    out = []
    for c in res.get("content") or []:
        if isinstance(c, dict) and isinstance(c.get("text"), str):
            try:
                out.append(json.loads(c["text"]))
            except ValueError:
                pass
    if res.get("structuredContent") is not None:
        out.append(res["structuredContent"])
    return out


def _dicts_with(values, *keys):
    """Every dict, at any depth of values, that has one of keys."""
    found, todo = [], list(values)
    while todo:
        v = todo.pop()
        if isinstance(v, dict):
            if any(k in v for k in keys):
                found.append(v)
            todo.extend(v.values())
        elif isinstance(v, list):
            todo.extend(v)
    return found


def _dashboard_owns_gateway(token):
    """True when the dashboard says this token's user is the owner and
    launched this gateway."""
    _, sid = _dashboard_call(token, "initialize", {"protocolVersion": "2025-03-26", "capabilities": {},
                                                   "clientInfo": {"name": MCP_NAME, "version": "1"}})
    # The dashboard expects validate_user before other calls in a session.
    resp, _ = _dashboard_call(token, "tools/call", {"name": "validate_user",
                                                    "arguments": {"username": GATEWAY_OWNER}}, sid)
    if (resp.get("result") or {}).get("isError"):
        return False
    for info in _dicts_with(_dashboard_json(resp), "allow_mcp", "user_account", "user_id"):
        if info.get("allow_mcp") is False:
            return False
        names = [str(info[k]) for k in ("user_account", "user_id") if k in info]
        if names and GATEWAY_OWNER not in names:
            return False
    resp, _ = _dashboard_call(token, "tools/call", {"name": "get_my_mcp_servers",
                                                    "arguments": {"unused": ""}}, sid)
    if (resp.get("result") or {}).get("isError"):
        return False
    entries = _dicts_with(_dashboard_json(resp), "mcp_name")
    if not entries:
        _hlog("dashboard listing not recognised")
        return False
    job = os.environ.get("SLURM_JOB_ID", "")
    for e in entries:
        if e["mcp_name"] != MCP_NAME or ("owner" in e and e["owner"] != GATEWAY_OWNER):
            continue
        if job and e.get("slurm_job_id") not in (None, "") and str(e["slurm_job_id"]) != job:
            continue
        return True
    return False


def _dashboard_identify(token, h):
    if not DASHBOARD_AUTH or AUTH_MODE == "token" or len(token) < 16:
        return ""        # with a gateway token the dashboard is never asked
    now = time.time()
    with _DASH_LOCK:
        hit = _DASH_CACHE.get(h)
        if hit and hit[1] > now:
            return hit[0]
    try:
        user = GATEWAY_OWNER if _dashboard_owns_gateway(token) else ""
        ttl = 600 if user else 60
    except Exception as e:
        _hlog(f"dashboard check failed: {type(e).__name__}")
        user, ttl = "", 15
    with _DASH_LOCK:
        if len(_DASH_CACHE) > 256:
            _DASH_CACHE.clear()
        _DASH_CACHE[h] = (user, now + ttl)
    return user


def _resolve_user(username):
    """The user this request acts as — always the token's user."""
    bound = getattr(_tls, "user", "")
    if not bound:
        return "", {"status": "unauthorized", "code": "AUTH_REQUIRED", "message": AUTH_HELP}
    asked = (username or "").strip()
    if asked and asked != bound:
        return "", {"status": "error", "code": "IDENTITY_MISMATCH",
                    "message": f"this token belongs to {bound}; it cannot act as {asked}"}
    return bound, None


def _hops(u):
    """(login hop open, whole chain open) for u's two-hop chain."""
    gw, fa = _socks(u)
    login = _master_alive(gw, f"{u}@{SITE['login_host']}")
    return login, login and _master_alive(fa, f"{u}@localhost", ["-p", str(_fwd_port(u))])


def _chain_alive(u):
    return _hops(u)[1]


def _need_user(username):
    """Resolve the acting user AND require a live chain."""
    u, err = _resolve_user(username)
    if err:
        return u, err
    if not _chain_alive(u):
        return u, {"status": "disconnected", "code": "CHAIN_DOWN", "username": u,
                   "message": f"no live chain for {u}; call connect_hpc first"}
    return u, None


# ── audit ───────────────────────────────────────────────────────────────────
#
# Every tools/call, every background job and every write effect leaves one
# JSON line in ACCESS_DIR/audit.jsonl (mode 600). The lines are chained: each
# carries the sha256 of the previous line, so a removed or edited line breaks
# the chain, which audit_verify.py checks. A record says who acted (the
# token's user, and the user acted as), the tool, the argument KEYS and a
# digest of the arguments, the outcome's status and code, and the duration.
# Argument values are never written: the PIN, passwords, GitHub tokens and
# campaign cards stay out of the log.

AUDIT_FILE = os.path.join(ACCESS_DIR, "audit.jsonl")
SECRET_ARGS = {"pin_otp", "password", "github_token", "token", "confirm"}
_AUDIT_LOCK = threading.Lock()
_AUDIT = {"fd": None, "prev": "0" * 64, "seq": 0}


def _canonical_sha256(obj):
    return hashlib.sha256(json.dumps(obj, sort_keys=True, separators=(",", ":"), default=str).encode()).hexdigest()


def _printable(s, limit=64):
    return "".join(ch for ch in str(s or "") if 32 <= ord(ch) < 127)[:limit]


def _audit_open():
    """Open the log for appending and continue its chain from its last line.
    Called at start-up, never at import (deploy_and_verify imports this module)."""
    _ensure_access_dir()
    broken = False
    with _AUDIT_LOCK:
        if _AUDIT["fd"] is not None:
            return
        fd = os.open(AUDIT_FILE, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        os.fchmod(fd, 0o600)
        prev, seq = "0" * 64, 0
        try:
            with open(AUDIT_FILE, "rb") as fh:
                fh.seek(0, os.SEEK_END)
                size = fh.tell()
                fh.seek(max(0, size - 65536))
                lines = [ln for ln in fh.read().split(b"\n") if ln.strip()]
            if lines:
                try:
                    seq = int(json.loads(lines[-1])["seq"])
                    prev = hashlib.sha256(lines[-1]).hexdigest()
                except (ValueError, KeyError, TypeError):
                    broken = True
        except OSError:
            pass
        _AUDIT.update(fd=fd, prev=prev, seq=seq)
    if broken:
        _audit("audit.recover", note="the last line of the log could not be parsed; the chain restarts here")


def _audit(kind, **fields):
    """Append one record. Returns its sha256 (the next record's prev), or None
    when nothing could be written; a failure to log never fails the call."""
    try:
        if _AUDIT["fd"] is None:
            _audit_open()
        now = time.time()
        rec = {"v": 1, "kind": kind, "ts": time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(now)) + f".{int(now * 1000) % 1000:03d}Z",
               "gateway": MCP_NAME, "owner": GATEWAY_OWNER, "job": os.environ.get("SLURM_JOB_ID"), **fields}
        with _AUDIT_LOCK:
            rec["seq"] = _AUDIT["seq"] + 1
            rec["prev"] = _AUDIT["prev"]
            line = json.dumps(rec, sort_keys=True, separators=(",", ":"), default=str)
            digest = hashlib.sha256(line.encode()).hexdigest()
            os.write(_AUDIT["fd"], (line + "\n").encode())
            _AUDIT["seq"], _AUDIT["prev"] = rec["seq"], digest
        _audit_queue(fields.get("acting") or fields.get("user") or "", line)
        return digest
    except Exception:
        return None


def _audit_call(name, args, result, t0, rid):
    """The record of one tools/call, whatever its outcome."""
    try:
        status, code, is_error = _outcome(result)
        if code == "UNKNOWN_TOOL" and TOOLS.get(name, {}).get("denied"):
            code = "TOOL_DENIED"
        a = args if isinstance(args, dict) else {}
        public = {k: v for k, v in a.items() if k not in SECRET_ARGS}
        _audit("call", principal=getattr(_tls, "principal", ""), acting=getattr(_tls, "user", ""),
               auth=getattr(_tls, "auth", ""), sid=_printable(getattr(_tls, "sid", "")), rid=_printable(rid),
               client=_printable(getattr(_tls, "client", ""), 40), tool=str(name)[:80],
               arg_keys=sorted(str(k) for k in a)[:40], args_sha256=_canonical_sha256(public) if public else None,
               confirmation_sha256=_sha(str(a["confirm"]).strip()) if a.get("confirm") else None,
               outcome={"status": status, "code": code, "is_error": is_error},
               duration_ms=int((time.monotonic() - t0) * 1000))
    except Exception:
        pass


# The ifarm mirror. Records about a user are also appended to
# <area>/.jam_audit.jsonl through that user's own chain, so a copy exists where
# the gateway (same uid, same node) cannot quietly rewrite it. Lines wait while
# the chain is down; a flush follows every write effect and runs every 30 s.
AUDIT_MIRROR = os.environ.get("JAM_GW_AUDIT_MIRROR", "1") != "0"
_AUDIT_PENDING = {}
_AUDIT_PENDING_CAP = 2000


def _audit_queue(user, line):
    if not AUDIT_MIRROR or not user or not re.fullmatch(USERNAME_RE, user):
        return
    with _AUDIT_LOCK:
        q = _AUDIT_PENDING.setdefault(user, [])
        q.append(line)
        dropped = max(0, len(q) - _AUDIT_PENDING_CAP)
        del q[:dropped]
    if dropped:
        _audit("audit.mirror_dropped", user=user, n=dropped)


def _audit_mirror_flush(user):
    """Append the user's pending lines to the mirror, when the chain is up."""
    with _AUDIT_LOCK:
        lines = list(_AUDIT_PENDING.get(user) or [])
    if not lines:
        return
    try:
        if not _chain_alive(user):
            return
        area = _area(user)
        r = _remote(user, f"umask 077; mkdir -p {_shq(area)} && cat >> {_shq(area + '/.jam_audit.jsonl')}",
                    stdin="".join(ln + "\n" for ln in lines), timeout=30)
        if r.get("rc") == 0:
            with _AUDIT_LOCK:
                del (_AUDIT_PENDING.get(user) or [])[:len(lines)]
    except Exception:
        pass


def _audit_mirror_loop():
    while True:
        time.sleep(30)
        for user in list(_AUDIT_PENDING):
            _audit_mirror_flush(user)


def _effect(effect, user, **fields):
    """The record of one write effect (a submission, a cancel, a delete, a
    workspace change, a sign-in), flushed to the mirror right away."""
    _audit("effect", effect=effect, user=user, principal=getattr(_tls, "principal", ""),
           sid=_printable(getattr(_tls, "sid", "")), **fields)
    threading.Thread(target=_audit_mirror_flush, args=(user,), daemon=True).start()


# ── chain ───────────────────────────────────────────────────────────────────

def _close_master(sock, dest, opts=None):
    """Before a hop is rebuilt: close its master if it still answers, then
    remove a stale socket file."""
    if _master_alive(sock, dest, opts):
        _run(["ssh", "-S", sock, "-O", "exit"] + (opts or []) + [dest], timeout=15)
    try:
        os.unlink(sock)
    except OSError:
        pass


def connect_hpc(username="", pin_otp="", password=""):
    out = _connect_hpc(username, pin_otp, password)
    # The sign-in is a write effect (it opens the chain every cluster tool
    # uses); only its outcome is recorded, never the credentials.
    if out.get("username"):
        _effect("connect_hpc", out["username"], status=out.get("status"), step=out.get("step"),
                connected=bool(out.get("connected")))
    return out


def _connect_hpc(username, pin_otp, password):
    u, err = _resolve_user(username)
    if err:
        return dict(err, connected=False)
    os.makedirs(CM_DIR, mode=0o700, exist_ok=True)
    gw, fa = _socks(u)
    gwd = f"{u}@{SITE['login_host']}"
    port = str(_fwd_port(u))
    login_open, alive = _hops(u)
    # reuse FIRST — never touch a live chain
    if alive:
        check = _remote(u, "hostname; whoami; date -u", timeout=30)
        return {"status": "reused", "connected": True, "username": u,
                "note": "existing ControlMasters alive — no OTP needed",
                "remote": check["out"][:200], "check": check["rc"]}
    # What is needed is decided before any socket is touched: a live login
    # hop carries a new compute hop, so then only the password is asked for.
    needs = ([] if login_open or pin_otp else ["pin_otp"]) + ([] if password else ["password"])
    if needs:
        what = (f"{SITE['login_host']} is still open, so only the {SITE['compute_secret']} for "
                f"{SITE['compute_host']} (password) is needed" if login_open else
                f"Signing in needs the {SITE['login_secret']} for {SITE['login_host']} (pin_otp, "
                f"no space) and the {SITE['compute_secret']} for {SITE['compute_host']} (password)")
        return {"status": "error", "connected": False, "username": u, "needs": needs,
                "message": what + ". Credentials are typed on the panel's Connect tab "
                                  "(get_console tab=connect), never in chat."}
    hop_opts = ["-o", "ControlPersist=8h", "-o", "StrictHostKeyChecking=accept-new",
                "-o", "NumberOfPasswordPrompts=2", "-o", "PubkeyAuthentication=no",
                "-o", "PreferredAuthentications=keyboard-interactive,password"]
    # The compute hop is always rebuilt: it is down, or it rode a login hop
    # that is. The login hop is rebuilt only when it is down.
    _close_master(fa, f"{u}@localhost", ["-p", port])
    if not login_open:
        _close_master(gw, gwd)
        r1 = _run(["setsid", "ssh", "-M", "-S", gw, *hop_opts, "-fN", gwd],
                  timeout=40, secret=pin_otp)
        if not _master_alive(gw, gwd):
            return {"status": "error", "connected": False, "step": "gateway", "username": u,
                    "message": f"{SITE['login_host']} failed: {r1['err'][-400:] or r1['out'][-200:]}"}
    # A forward the login hop already has is accepted as it is, so this also
    # restores one that a live login hop lost.
    r2 = _run(["ssh", "-S", gw, "-O", "forward",
               "-L", f"127.0.0.1:{port}:{SITE['compute_host']}:22", gwd], timeout=20)
    if r2["rc"] != 0:
        return {"status": "error", "connected": False, "step": "forward", "username": u,
                "message": r2["err"][-300:]}
    r3 = _run(["setsid", "ssh", "-M", "-S", fa, *hop_opts, "-fN",
               "-p", port, f"{u}@localhost"], timeout=40, secret=password)
    if not _master_alive(fa, f"{u}@localhost", ["-p", port]):
        return {"status": "error", "connected": False, "step": "compute", "username": u,
                "message": f"{SITE['compute_host']} failed: {r3['err'][-400:] or r3['out'][-200:]}"}
    check = _remote(u, "hostname; whoami; date -u", timeout=60)
    return {"status": "ok", "connected": True, "username": u, "site": SITE["id"],
            "chain": f"node->{SITE['login_host']}->{SITE['compute_host']}",
            "remote": check["out"][:300], "check": check["rc"]}


# ── tools (flat, one per function) ──────────────────────────────────────────

def ping():
    return "pong from LQCD gateway node"


PANEL_TABS = ("connect", "project", "campaign", "collections", "analysis")


def _panel_urls(tab="connect"):
    # Any browser GET of the gateway URL is answered with the panel.
    q = "?tab=" + urllib.parse.quote(tab)
    return [{"entry": "direct", "url": (PUBLIC_URL or f"{PROXY}/cloud/{MCP_NAME}/mcp") + q}]


def get_console(tab="connect"):
    tab = tab if tab in PANEL_TABS else "connect"
    return {
        "panel_urls": _panel_urls(tab),
        "guidance": "Give the user a panel_url to open in a browser. Tabs: Connect (sign in to "
                    "the cluster), Project (check or create the workspace), Campaign (build and "
                    "submit a fit), Collections (campaigns, the Slurm queue, stop or delete a "
                    "campaign) and Analysis (postprocess, fit summary, PDF plots, by experiment, "
                    "logs, more replicas). Cluster credentials are typed only on that page, never into "
                    "chat. The page asks once for the user's LQCDMCP dashboard token."}


# ── deploy (hot upgrade) ─────────────────────────────────────────────────────
#
# hot_redeploy.py replaces the running gateway's code inside the same Slurm
# job through the hidden tool `deploy`: eight fixed operations, never a shell.
# Files are staged under APP_DIR/.hot_redeploy.stage-<stage>, hashed and
# import-checked in a fresh interpreter (verify) before install swaps them in,
# and restart stops this process so the job's supervisor loop starts the new
# one. The tool needs the owner's token AND the admin secret (X-JAM-Admin, or
# _meta "jam/admin" when a proxy strips the header); without ADMIN_SHA256 it
# is off, and the gateway is upgraded by relaunching the job.

APP_DIR = os.path.realpath(os.environ.get("JAM_GW_APP_DIR") or HERE)
_STARTED = time.time()
_DEPLOY_LOCK = threading.Lock()
_DEPLOY_CHUNKS = {}                  # (stage, rel) -> next chunk index expected
DEPLOY_COMPONENTS = ("jamai", "plugins", "analyses", "jam_panel.html", "jam_gateway.py")
DEPLOY_CHUNK_B64_MAX = 400_000       # about 300 KB per chunk

# Runs in a fresh python3 -B inside the stage: the staged gateway must import,
# with its complete package, from the stage alone.
_STAGE_CHECK_PROGRAM = r"""
import hashlib, importlib, json, os, pathlib, sys
args = json.load(sys.stdin)
stage = pathlib.Path(args['stage']).resolve()
os.chdir(stage)
sys.path.insert(0, str(stage))
for rel, expected in args['hashes'].items():
    path = stage / rel
    if hashlib.sha256(path.read_bytes()).hexdigest() != expected:
        raise RuntimeError('staged hash mismatch: ' + rel)
    if path.suffix == '.py':
        compile(path.read_bytes(), str(path), 'exec')
gateway = importlib.import_module('jam_gateway')
catalog_root = gateway.analysis_catalog.catalog_root(stage)
if catalog_root.resolve() != (stage / 'analyses').resolve():
    raise RuntimeError('catalog escaped staged application')
if not gateway.analysis_catalog.Catalog(catalog_root).deployment_files():
    raise RuntimeError('no validated scientific catalog entries were staged')
results_root = gateway.analysis_results.results_root(stage)
if results_root.resolve() != (stage / 'analyses').resolve():
    raise RuntimeError('results manifests escaped staged application')
if not gateway.analysis_results.Results(results_root).deployment_files():
    raise RuntimeError('no validated reference-results manifests were staged')
for name, module in list(sys.modules.items()):
    if (name == 'jam_gateway' or name == 'jamai' or name.startswith('jamai.')
            or name == 'jam_plugins' or name.startswith('jam_plugin_')):
        path = pathlib.Path(module.__file__).resolve()
        if stage not in path.parents:
            raise RuntimeError('import escaped staged application: ' + name)
errors = getattr(gateway, 'PLUGIN_STATUS', {}).get('errors') or {}
if errors:
    raise RuntimeError('plugin failed to load: ' + '; '.join(n + ': ' + w for n, w in errors.items()))
print('IMPORT-OK')
"""


def _deploy_stage_dir(stage):
    if not re.fullmatch(r"\d{10,20}", str(stage or "")):
        raise ValueError("BAD_STAGE")
    return os.path.join(APP_DIR, f".hot_redeploy.stage-{stage}")


def _deploy_rel(rel):
    """A relative path inside the application package, or ValueError."""
    rel = str(rel or "")
    norm = os.path.normpath(rel).replace(os.sep, "/")
    parts = norm.split("/")
    if (not rel or rel.startswith("/") or norm != rel.rstrip("/") or ".." in parts or "" in parts
            or not (norm in ("jam_gateway.py", "jam_panel.html") or norm.startswith(("jamai/", "plugins/", "analyses/")))):
        raise ValueError("BAD_PATH")
    return norm


def _deploy_result(ok, **fields):
    return {"ok": ok, **fields}


def deploy(args):
    """The hot-upgrade operations; see the section comment."""
    op = str(args.get("op") or "")
    u = GATEWAY_OWNER
    try:
        if op == "status":
            with _DEPLOY_LOCK:
                stages = sorted(d[len(".hot_redeploy.stage-"):] for d in os.listdir(APP_DIR)
                                if d.startswith(".hot_redeploy.stage-")) if os.path.isdir(APP_DIR) else []
            return _deploy_result(True, slurm_job_id=os.environ.get("SLURM_JOB_ID"), app_dir=APP_DIR,
                                  cwd=os.path.realpath(os.getcwd()), gateway_sha256=_GATEWAY_SHA256,
                                  started_at=_STARTED, uptime_s=round(time.time() - _STARTED), version="0.9.0",
                                  auth_mode=AUTH_MODE, admin_via=getattr(_tls, "admin_via", None), stages=stages,
                                  audit_seq=_AUDIT["seq"])
        if op == "node_info":
            try:
                load1 = os.getloadavg()[0]
            except OSError:
                load1 = None
            st = os.statvfs(os.path.expanduser("~"))
            socks = sorted(os.listdir(CM_DIR)) if os.path.isdir(CM_DIR) else []
            return _deploy_result(True, hostname=socket.gethostname(), user=GATEWAY_OWNER, python=sys.version.split()[0],
                                  load1=load1, home_free_mb=round(st.f_bavail * st.f_frsize / 2**20), cm_sockets=socks)
        if op == "restart":
            if not os.environ.get("SLURM_JOB_ID"):
                return _refuse("NOT_A_JOB", "this gateway is not a Slurm job, so nothing would start it again")
            if os.path.realpath(os.getcwd()) != APP_DIR:
                return _refuse("NOT_A_JOB", f"this gateway does not run from {APP_DIR}")
            _effect("deploy.restart", u, pid=os.getpid())
            threading.Timer(1.0, os.kill, (os.getpid(), signal.SIGTERM)).start()
            return _deploy_result(True, pid=os.getpid(), in_s=1)
        stage_dir = _deploy_stage_dir(args.get("stage"))
        if op == "stage_chunk":
            rel = _deploy_rel(args.get("rel"))
            index = args.get("index")
            data = str(args.get("data_b64") or "")
            if type(index) is not int or index < 0 or len(data) > DEPLOY_CHUNK_B64_MAX:
                return _refuse("BAD_ARGUMENT", "index: a chunk number from 0; data_b64: at most %d characters"
                               % DEPLOY_CHUNK_B64_MAX)
            try:
                chunk = base64.b64decode(data, validate=True)
            except (ValueError, binascii.Error):
                return _refuse("BAD_ARGUMENT", "data_b64 is not base64")
            part = os.path.join(stage_dir, rel + ".part")
            with _DEPLOY_LOCK:
                expected = _DEPLOY_CHUNKS.get((stage_dir, rel), 0)
                if index != expected:
                    return _refuse("BAD_ARGUMENT", f"chunk {index} out of order; {expected} is next")
                os.makedirs(os.path.dirname(part), mode=0o700, exist_ok=True)
                if index == 0:
                    fd = os.open(part, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                else:
                    fd = os.open(part, os.O_WRONLY | os.O_APPEND)
                with os.fdopen(fd, "wb") as fh:
                    fh.write(chunk)
                _DEPLOY_CHUNKS[(stage_dir, rel)] = index + 1
            return _deploy_result(True, rel=rel, index=index, bytes=len(chunk))
        if op == "stage_finish":
            rel = _deploy_rel(args.get("rel"))
            part, final = os.path.join(stage_dir, rel + ".part"), os.path.join(stage_dir, rel)
            with open(part, "rb") as fh:
                content = fh.read()
            if hashlib.sha256(content).hexdigest() != str(args.get("sha256") or "").lower():
                os.remove(part)
                return _refuse("HASH_MISMATCH", f"{rel}: the staged bytes do not match sha256")
            compiled = False
            if rel.endswith(".py"):
                compile(content, rel, "exec")        # SyntaxError -> INTERNAL_ERROR below, nothing installed
                compiled = True
            os.replace(part, final)
            with _DEPLOY_LOCK:
                _DEPLOY_CHUNKS.pop((stage_dir, rel), None)
            return _deploy_result(True, rel=rel, sha256=hashlib.sha256(content).hexdigest(), compiled=compiled)
        if op == "verify":
            hashes = args.get("hashes")
            if not isinstance(hashes, dict) or not hashes:
                return _refuse("BAD_ARGUMENT", "hashes: {relative path: sha256} of every staged file")
            for rel in hashes:
                _deploy_rel(rel)
            p = subprocess.run([sys.executable, "-B", "-c", _STAGE_CHECK_PROGRAM],
                               input=json.dumps({"stage": stage_dir, "hashes": hashes}),
                               capture_output=True, text=True, cwd=stage_dir, timeout=120)
            output = ((p.stdout or "") + (p.stderr or ""))[-2000:]
            if p.returncode != 0 or "IMPORT-OK" not in (p.stdout or ""):
                _effect("deploy.verify", u, stage=os.path.basename(stage_dir), ok=False)
                return _refuse("VERIFY_FAILED", "the staged application does not load on the node", output=output)
            with open(os.path.join(stage_dir, ".verified"), "w") as fh:
                fh.write(_canonical_sha256(hashes) + "\n")
            _effect("deploy.verify", u, stage=os.path.basename(stage_dir), files=len(hashes), ok=True)
            return _deploy_result(True, files=len(hashes), output=output[-400:])
        if op == "install":
            if not os.path.exists(os.path.join(stage_dir, ".verified")):
                return _refuse("VERIFY_FAILED", "verify this stage first")
            backup = os.path.join(APP_DIR, ".hot_redeploy.previous")
            saved, installed = [], []
            with _DEPLOY_LOCK:
                if os.path.exists(backup):
                    shutil.rmtree(backup)
                os.mkdir(backup, 0o700)
                try:
                    for name in DEPLOY_COMPONENTS:
                        if os.path.exists(os.path.join(APP_DIR, name)):
                            shutil.move(os.path.join(APP_DIR, name), os.path.join(backup, name))
                            saved.append(name)
                        if name == "plugins" and not os.path.exists(os.path.join(stage_dir, name)):
                            continue                # an application without plugins
                        shutil.move(os.path.join(stage_dir, name), os.path.join(APP_DIR, name))
                        installed.append(name)
                except BaseException:
                    for name in reversed(installed):
                        target = os.path.join(APP_DIR, name)
                        shutil.rmtree(target) if os.path.isdir(target) else os.unlink(target)
                    for name in reversed(saved):
                        shutil.move(os.path.join(backup, name), os.path.join(APP_DIR, name))
                    _effect("deploy.install", u, stage=os.path.basename(stage_dir), ok=False)
                    raise
            _effect("deploy.install", u, stage=os.path.basename(stage_dir), installed=installed, ok=True)
            return _deploy_result(True, installed=installed, previous=backup)
        if op == "clean":
            removed = os.path.isdir(stage_dir)
            if removed:
                shutil.rmtree(stage_dir)
            with _DEPLOY_LOCK:
                for key in [k for k in _DEPLOY_CHUNKS if k[0] == stage_dir]:
                    del _DEPLOY_CHUNKS[key]
            return _deploy_result(True, removed=removed)
        return _refuse("BAD_ARGUMENT", "op: status, node_info, stage_chunk, stage_finish, verify, install, clean or restart")
    except ValueError as e:
        if str(e) in ("BAD_STAGE", "BAD_PATH"):
            return _refuse(str(e), {"BAD_STAGE": "stage: 10 to 20 digits (a timestamp)",
                                    "BAD_PATH": "rel: a path inside the application package"}[str(e)])
        raise
    except FileNotFoundError as e:
        return _refuse("BAD_PATH", f"nothing staged at {e.filename}")


def _outside_read_roots(p, user=""):
    roots = list(SITE["read_roots"])
    if user:
        roots.append(f"{SITE.get('slurm_log_root', '/farm_out').rstrip('/')}/{user}")
    if any(p == r or p.startswith(r.rstrip("/") + "/") for r in roots):
        return None
    return _refuse("OUTSIDE_READ_ROOTS", "path must be under " + " or ".join(roots))


# fs_list and fs_read run a python3 snippet on the compute host, which reports
# the true size, the window it returns and whether more remains. The ssh helper
# keeps only the last `cap` characters of stdout, so a tool that returned the
# raw command output could show half a file without saying so (a 9 KB log,
# a 60-line `ls -la`): these replies always say what was left out.
_FS_LIST_BODY = r'''
import json
REQ = json.loads(base64.b64decode(_REQ))
p, limit = REQ["path"], max(1, min(int(REQ.get("limit") or 60), 200))
try:
    entries = list(os.scandir(p))
except OSError as e:
    print(json.dumps({"error": "%s: %s" % (type(e).__name__, e)})); raise SystemExit(0)
entries.sort(key=lambda e: e.name.lower())
rows = []
for e in entries[:limit]:
    row = {"name": e.name}
    try:
        st = e.stat(follow_symlinks=False)
        row.update(kind="dir" if e.is_dir(follow_symlinks=False) else ("link" if e.is_symlink() else "file"),
                   size=st.st_size, mtime=time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(st.st_mtime)))
    except OSError as x:
        row.update(kind="unreadable", error=str(x))
    rows.append(row)
print(json.dumps({"total_entries": len(entries), "returned": len(rows),
                  "truncated": len(entries) > len(rows), "entries": rows}))
'''

_FS_READ_BODY = r'''
import json
REQ = json.loads(base64.b64decode(_REQ))
p = REQ["path"]
try:
    st = os.stat(p)
except OSError as e:
    print(json.dumps({"error": "%s: %s" % (type(e).__name__, e)})); raise SystemExit(0)
if os.path.isdir(p):
    print(json.dumps({"error": "is a directory: use fs_list to list it"})); raise SystemExit(0)
total = st.st_size
offset = min(max(0, int(REQ.get("offset") or 0)), total)
max_bytes = max(1, min(int(REQ.get("max_bytes") or 4000), 20000))
with open(p, "rb") as f:
    f.seek(offset)
    raw = f.read(max_bytes)
lines_wanted = int(REQ.get("max_lines") or 0)
if lines_wanted > 0:
    parts = raw.splitlines(keepends=True)
    if len(parts) > lines_wanted:
        raw = b"".join(parts[:lines_wanted])
text = raw.decode("utf-8", "replace")
end = offset + len(raw)
print(json.dumps({"total_bytes": total, "offset": offset, "returned_bytes": len(raw),
                  "returned_lines": text.count("\n") + (1 if text and not text.endswith("\n") else 0),
                  "truncated": end < total, "next_offset": end if end < total else None,
                  "content": text}))
'''


def _fs_snippet(body, request):
    payload = base64.b64encode(json.dumps(request).encode()).decode()
    return "import os, time, base64\n" + f"_REQ = {payload!r}\n" + body


def _fs_reply(p, r, what):
    """The snippet's JSON, or an error that repeats what the host answered."""
    text = (r.get("out") or "").strip()
    try:
        data = json.loads(text.splitlines()[-1]) if text else {}
    except ValueError:
        data = {}
    if r.get("rc") != 0 or not isinstance(data, dict) or not data:
        tail = (r.get("err") or "").strip()[-400:] or text[-400:] or "no output"
        return {"status": "error", "code": "READ_FAILED",
                "message": f"Could not {what} {p} on the compute host: {tail}"}
    if data.get("error"):
        return {"status": "error", "code": "READ_FAILED", "message": f"{p}: {data['error']}"}
    return data


def fs_list(path="", limit=60, username=""):
    u, err = _need_user(username)
    if err:
        return err
    p = os.path.normpath(path.strip() or _area(u))
    bad = _outside_read_roots(p, u)
    if bad:
        return bad
    try:
        limit = max(1, min(int(limit or 60), 200))
    except (TypeError, ValueError):
        return _refuse("BAD_ARGUMENT", "limit: a whole number from 1 to 200")
    r = _run_ifarm_py(u, _fs_snippet(_FS_LIST_BODY, {"path": p, "limit": limit}), timeout=90, cap=80000)
    data = _fs_reply(p, r, "list")
    if data.get("status") == "error":
        return data
    out = {"status": "ok", "username": u, "path": p, **data}
    if data.get("truncated"):
        out["hint"] = (f"{data['total_entries']} entries; showing the first {data['returned']} by name. "
                       "Name a subdirectory or a file instead of raising the limit.")
    return out


def fs_read(path="", max_lines=0, offset=0, max_bytes=0, username=""):
    u, err = _need_user(username)
    if err:
        return err
    p = os.path.normpath(path.strip())
    if not p or p == ".":
        return _refuse("BAD_ARGUMENT", "path: the file to read")
    bad = _outside_read_roots(p, u)
    if bad:
        return bad
    try:
        offset = max(0, int(offset or 0))
        max_bytes = max(1, min(int(max_bytes or 4000), 20000))
        max_lines = max(0, min(int(max_lines or 0), 500))
    except (TypeError, ValueError):
        return _refuse("BAD_ARGUMENT", "offset, max_bytes and max_lines take whole numbers")
    r = _run_ifarm_py(u, _fs_snippet(_FS_READ_BODY, {"path": p, "offset": offset, "max_bytes": max_bytes,
                                                     "max_lines": max_lines}), timeout=90, cap=120000)
    data = _fs_reply(p, r, "read")
    if data.get("status") == "error":
        return data
    out = {"status": "ok", "username": u, "path": p, **data}
    if data.get("truncated"):
        out["hint"] = (f"Showing bytes {data['offset']}-{data['offset'] + data['returned_bytes']} of "
                       f"{data['total_bytes']} ({data['returned_lines']} lines). Call fs_read again with "
                       f"offset={data['next_offset']} for the rest; max_bytes is at most 20000.")
    return out


# A workspace path goes into shell commands and Slurm scripts on the cluster,
# so it may hold only these characters.
WORKSPACE_PATH_RE = r"/[A-Za-z0-9._/-]+"
# The recorded workspace folder was deleted or moved: a branch switch cannot help.
WORKSPACE_GONE = ("The workspace folder {} no longer exists: choose another workspace on the Project "
                  "tab or create a new one.")


def setup_workspace(repo_url="", github_token="", target_dir="", username="",
                    folder_name="", branch=""):
    """git clone the JAM code (the FitPack `ai` branch) to target_dir (default
    <area>/fitpack_legacy), record it as THE workspace and link the shared
    interpolation grids. A folder that is already there is not cloned again.

    repo_url defaults to the JAM repository. folder_name is the panel's way of
    naming target_dir inside the user's own area; branch picks the branch to
    clone. The clone can take minutes, so this runs as a background job the
    client polls with analysis_result (the token never enters the job's key)."""
    u, err = _need_user(username)
    if err:
        return dict(err, ok=False)
    params = {"repo_url": repo_url, "target_dir": target_dir, "folder_name": folder_name, "branch": branch}
    return _background(u, "setup_workspace", params,
                       lambda: _setup_workspace(u, repo_url, github_token, target_dir, folder_name, branch),
                       wait=CAMPAIGN_WAIT)


def _setup_workspace(u, repo_url, github_token, target_dir, folder_name, branch):
    root = _area(u)
    folder = (folder_name or "").strip()
    if folder and not re.fullmatch(r"[A-Za-z0-9._-]{1,64}", folder):
        return {"status": "error", "ok": False,
                "message": "Folder name may use letters, numbers, '.', '_' and '-' only."}
    target = os.path.normpath((target_dir or "").strip()
                              or (f"{root}/{folder}" if folder else f"{root}/fitpack_legacy"))
    if not target.startswith(root + "/"):
        return {"status": "error", "ok": False,
                "message": f"The workspace must be inside your own area ({root})."}
    if not re.fullmatch(WORKSPACE_PATH_RE, target):
        return {"status": "error", "ok": False,
                "message": "The workspace path may use letters, numbers, '.', '_', '-' and '/' only."}
    # The FitPack `ai` branch carries fitlib/ai.py, which runs campaigns (as
    # the JAM app's "Clone / Sync FitPack" does); another branch on request.
    br = (branch or "").strip() or ("ai" if (repo_url or "").strip() in ("", JAM_REPO_URL) else "")
    if br and not re.fullmatch(r"[A-Za-z0-9._/-]{1,100}", br):
        return {"status": "error", "ok": False,
                "message": "Branch name may use letters, numbers, '.', '_', '/' and '-' only."}
    steps = []
    exists = _remote(u, f"test -d {_shq(target)} && echo YES || echo NO", timeout=30)
    present = "YES" in (exists.get("out") or "")
    if present:
        steps.append("workspace already present — skipped clone")
    else:
        url = repo_url.strip() or JAM_REPO_URL
        tok = (github_token or "").strip()
        bflag = f"-b {_shq(br)} " if br else ""
        # The token never goes on a command line, where anyone on either host
        # could read it: it comes in on ssh's standard input, and a credential
        # helper for the repository's host alone hands it to git. The helpers
        # the user has configured are switched off for this clone, so none
        # stores it, and the clone's .git/config never sees it.
        host = re.match(r"https://[^/]+", url) if tok else None
        auth = read = ""
        if host:
            helper = ('!f() { test "$1" = get && echo username=x-access-token && '
                      'echo "password=$JAM_GH_TOKEN"; }; f')
            key = f"credential.{host.group(0)}.helper"
            auth = f"-c credential.helper= -c {_shq(key + '=' + helper)} "
            read = "IFS= read -r JAM_GH_TOKEN; export JAM_GH_TOKEN; "
        # pipefail: without it the exit status is tail's, and a failed clone
        # was reported as success. GIT_TERMINAL_PROMPT=0 makes a private repo
        # without a token fail at once instead of waiting out the timeout.
        # The helper starts with "!" and the login shell on the compute host
        # expands history, so the command travels base64-encoded into a plain
        # bash (no profile, no history expansion); the token still arrives on stdin.
        script = (f"set -o pipefail; {read}mkdir -p {_shq(os.path.dirname(target))} && "
                  f"GIT_TERMINAL_PROMPT=0 git {auth}clone {bflag}{_shq(url)} "
                  f"{_shq(target)} 2>&1 | tail -3")
        b64 = base64.b64encode(script.encode()).decode()
        try:
            out = _remote(u, f'bash -c "$(echo {b64} | base64 -d)"', timeout=900,
                          stdin=tok + "\n" if host else None)
        except subprocess.TimeoutExpired:
            return {"status": "error", "ok": False, "username": u, "reason": "timeout",
                    "message": "git clone did not finish within 15 minutes and may still be running on "
                               "the cluster. Wait a few minutes, then look at the workspace report "
                               "(check_project, or the panel's Project tab) before trying again."}
        if tok:
            out["out"] = (out.get("out") or "").replace(tok, "***")
        steps.append(f"git clone: rc={out['rc']} {out['out'][-200:]}")
        if out["rc"] != 0:
            text = (out.get("out") or "") + (out.get("err") or "")
            auth = re.search(r"Authentication failed|could not read Username|"
                             r"Repository not found|403", text) is not None
            return {"status": "error", "ok": False, "username": u, "steps": steps,
                    "reason": "auth" if auth else "clone",
                    "message": ("The repository needs a GitHub token. Tokens are typed on "
                                "the panel's Project tab, never in chat: open panel_url, "
                                "fill in the folder name and the token, and press Create." if auth
                                else "git clone failed; see the detail below."),
                    "panel_url": _panel_urls("project")[0]["url"],
                    "detail": text.replace(tok, "***")[-400:] if tok else text[-400:]}
    out = _remote(u, f"printf '%s\\n' {_shq(target)} > {root}/.jam_workspace && echo DONE", timeout=60)
    steps.append("workspace marker: " + (out.get("out") or "").strip()[-60:])
    _effect("setup_workspace", u, workspace=target)
    steps.append(_link_grids(u, target))
    _WS_CACHE.pop(u, None)
    message = (f"A folder named {os.path.relpath(target, root)} already exists in your area: it was "
               "not cloned again and is now your workspace. The report shows anything it lacks."
               if present else f"Workspace ready at {target}.")
    return {"status": "ok", "ok": True, "username": u, "workspace": target,
            "steps": steps, "message": message, "report": check_project(u)}


def _link_grids(u, ws):
    """Link each of the site's grids into <ws>/grids/ unless it is already
    there; a link whose target is gone is pointed at the site's grid again.
    A real folder or file is never touched. Returns a one-line summary."""
    links = SITE.get("grid_links") or {}
    if not links:
        return "grids: no links configured for this site"
    parts = []
    for name, target in sorted(links.items()):
        dest, src = _shq(f"{ws}/grids/{name}"), _shq(target)
        # -e follows links, so only a missing entry or a dangling link gets past it.
        parts.append(f"if [ -e {dest} ]; then echo KEPT; "
                     f"elif [ ! -e {src} ]; then echo NOSRC {_shq(name)}; "
                     f"elif [ -L {dest} ]; then ln -sfn {src} {dest} && echo LINKED; "
                     f"else mkdir -p $(dirname {dest}) && ln -s {src} {dest} && echo LINKED; fi")
    r = _remote(u, "; ".join(parts), timeout=60)
    out = r.get("out") or ""
    msg = (f"grids: {out.count('LINKED')} linked, {out.count('KEPT')} already there")
    missing = re.findall(r"NOSRC (\S+)", out)
    if missing:
        msg += f", source missing for: {', '.join(missing)}"
    return msg


def _site_public():
    """What the panel needs to label the sign-in steps for this site."""
    return {"id": SITE["id"], "label": SITE["label"],
            "hops": [{"host": SITE["login_host"], "secret": SITE["login_secret"]},
                     {"host": SITE["compute_host"], "secret": SITE["compute_secret"]}]}


def check_hpc_connection(username=""):
    """Cheap connection probe for the panel's Connect tab: is this user's
    two-hop chain open (and its login hop on its own), and which workspace is
    recorded."""
    u, err = _resolve_user(username)
    if err:
        return {"connected": False, "status": err.get("status"), "note": err["message"]}
    login_open, alive = _hops(u)
    account = {"username": u, "area": _area(u)}
    if alive:
        account["workspace"] = _workspace(u)
    return {"connected": alive, "login_open": login_open, "cluster_reachable": alive,
            "shared": SHARED, "owner": GATEWAY_OWNER,
            "auth": AUTH_MODE, "legacy_shared": SHARED and AUTH_MODE == "dashboard", "audit": True,
            "tools_denied": sorted(TOOLS_DENY), "human_gate": HUMAN_GATE,
            "account": account, "site": _site_public(), "sites": [_site_public()],
            "note": ("Ready to run fits." if alive else
                     "Not signed in to the cluster. Sign in on the Connect tab of the "
                     "panel page; the chain stays open until the gateway's daily "
                     "window closes.")}


# What a workspace needs for campaigns: (label, path inside it). The two .py
# paths are files the FitPack ai branch has; the rest are folders.
_PROJECT_ITEMS = [
    ("JAM code (fitpack_legacy)", ""), ("fitlib", "fitlib"), ("qcdlib", "qcdlib"),
    ("obslib", "obslib"), ("experimental data", "database"), ("interpolation grids", "grids"),
    ("campaign template (examples/input02.py)", "examples/input02.py"),
    ("campaign runner (fitlib/ai.py, FitPack ai branch)", "fitlib/ai.py")]


def check_project(username=""):
    """Workspace report for the Project tab: the recorded workspace, every
    checkout in the user's area, and whether each part is present."""
    u, err = _need_user(username)
    if err:
        return err
    root = _area(u)
    code = f"""
import os, json
root = {root!r}
items_spec = {_PROJECT_ITEMS!r}
grid_names = {sorted(SITE.get("grid_links") or {})!r}
marker = os.path.join(root, '.jam_workspace')
ws = open(marker).read().strip() if os.path.isfile(marker) else ''
cands = []
try:
    for name in sorted(os.listdir(root)):
        p = os.path.join(root, name)
        if os.path.isdir(os.path.join(p, 'fitlib')):
            cands.append(p)
except OSError:
    pass
default = os.path.join(root, 'fitpack_legacy')
active = ws or (default if os.path.isdir(default) else '')
items = []
if active:
    for label, rel in items_spec:
        p = os.path.join(active, rel) if rel else active
        if rel == 'grids' and grid_names:
            # Every grid the site links must resolve (a dangling link fails too).
            miss = [g for g in grid_names if not os.path.exists(os.path.join(p, g))]
            items.append({{'name': label, 'detail': p + ' — ' + str(len(grid_names) - len(miss))
                          + ' of ' + str(len(grid_names)) + ' grids', 'ok': not miss, 'missing': miss}})
            continue
        ok = os.path.exists(p) if rel.endswith('.py') else os.path.isdir(p)
        items.append({{'name': label, 'detail': p, 'ok': ok}})
print(json.dumps({{'marker': ws, 'active': active, 'candidates': cands, 'items': items}}))
"""
    r = _run_ifarm_py(u, code, timeout=60, cap=20000)
    try:
        d = json.loads(r["out"].strip().splitlines()[-1])
    except Exception:
        return {"status": "error", "username": u, "message": "could not read the workspace",
                "detail": r}
    cands = [{"path": p, "active": p == d["active"]} for p in d["candidates"]]
    if not d["active"]:
        return {"status": "ok", "username": u, "configured": False, "candidates": cands,
                "note": "No workspace chosen yet."}
    ai_files = {label for label, rel in _PROJECT_ITEMS if rel.endswith(".py")}
    # Each part by its path inside the workspace ("" is the workspace folder itself).
    have = {rel: it["ok"] for (_, rel), it in zip(_PROJECT_ITEMS, d["items"])}
    gone = not have[""]                 # then neither a branch switch nor new grid links can help
    for it in d["items"]:
        if it["ok"]:
            continue
        if it["name"] in ai_files and not gone:
            if have["fitlib/ai.py"]:
                # The runner is there, so the checkout is on the ai branch already and a
                # switch would not bring the template back.
                it["action"] = TEMPLATE_GONE
            else:
                it["action"] = ("This checkout is not on the FitPack ai branch. Switch it with 'Switch "
                                "to the ai branch' below, or create a new workspace.")
                it["fix"] = "use_ai_branch"
        elif "missing" in it and not gone:
            it["action"] = ("Missing: " + ", ".join(it["missing"]) + ". Press 'Use selected' below "
                            "to link the shared grids again.")
            it["fix"] = "use_workspace"
        else:
            it["action"] = "Run 'Set up a new workspace' to create a fresh checkout."
    ok = all(it["ok"] for it in d["items"])
    note = "" if ok else "Something is missing from this workspace — see the items marked ✕."
    if not d["marker"]:
        note = ("Using the default location; no workspace has been chosen explicitly. "
                + note).strip()
    return {"status": "ok", "username": u, "configured": True, "ok": ok,
            "workspace": d["active"], "items": d["items"], "candidates": cands, "note": note}


def use_workspace(path="", username=""):
    """Record an existing checkout in the user's own area as THE workspace."""
    u, err = _need_user(username)
    if err:
        return dict(err, ok=False)
    root = _area(u)
    p = os.path.normpath((path or "").strip())
    if not p.startswith(root + "/"):
        return {"ok": False, "code": "OUTSIDE_AREA", "message": f"The workspace must be inside your own area ({root})."}
    if not re.fullmatch(WORKSPACE_PATH_RE, p):
        return {"ok": False, "message": f"{p} has characters other than letters, numbers, '.', '_', '-' "
                                        "and '/'. Rename the folder, or choose another one."}
    out = _remote(u, f"test -d {_shq(p)}/fitlib && printf '%s\\n' {_shq(p)} > {root}/.jam_workspace "
                     f"&& echo USED", timeout=60)
    if "USED" not in (out.get("out") or ""):
        return {"ok": False, "message": f"{p} is not a fitpack checkout (no fitlib/ inside)."}
    _link_grids(u, p)
    _WS_CACHE.pop(u, None)
    _effect("use_workspace", u, workspace=p)
    return {"ok": True, "workspace": p, "report": check_project(u)}


def open_panel(tab="connect"):
    """Open the operations panel. Hosts that render MCP Apps show it inline;
    for the rest the result carries the browser URL."""
    tab = tab if tab in PANEL_TABS else "connect"
    conn = check_hpc_connection()
    return {"status": "ok", "tab": tab, "connection": conn, "panel_urls": _panel_urls(tab),
            "message": (f"Opened the FemtoMind panel on the {tab.capitalize()} tab. If it does "
                        "not appear inline, open a panel_url in a browser.")}


# ── campaigns (the JAM app composer, as tools) ─────────────────────────────
#
# The same pipeline as the FemtoMind JAM app: the user picks an object, its
# parameters, reactions, datasets and cuts, QCD settings and job settings;
# JAMAI copies the repository's examples/input02.py and appends the choices as
# an override block (input.py); a Slurm job array runs one replica per task
# through fitlib/ai.py (FitPack `ai` branch); postprocessing aggregates the
# replicas' fit_summary.json; plots are drawn from the replicas' .msr files.
#
# Fixed here relative to the app: parameter edits, cuts, datasets the template
# does not list, "Max iterations", "Optimizer" and TMC "off" now all reach the
# fit (see jamai/input_materializer.py and jamai/run_replica.py). The parameter
# table is read from the workspace's own examples/input02.py (the library),
# and only the rows the user changed go into the override block, so every
# other parameter stays exactly as the library has it.

