    ax11.text(0.7, 0.55, '$Q^2 \\, \\in \\,[52,60]$', transform=ax11.transAxes, fontsize=30)
    ax11.text(0.7, 0.62, '$Q^2 \\, \\in \\,[60,68]$', transform=ax11.transAxes, fontsize=30)
