    ax12.text(0.7, 0.82, '\\textrm{\\textbf{LHCb}}', transform=ax12.transAxes, fontsize=40)
    ax11.set_ylim(0.0, 0.3)
    ax12.set_ylim(-0.55, 0.3)
    majorLocator = MultipleLocator(0.1)
