def thesis_pidis_plot_proton_A1_Apa(datasets, output_file, interval):
    _selected_keys = {r + ':' + str(i) for (r, tables) in datasets.items() for i in tables}
    thy_plot = thy_band = thy_plot0 = thy_band0 = thy_point0 = None
